	public Conversion()
	{
		FDeptName = "機關";
		AppLocation = CommonMethods.ExtractFilePath(Application.ExecutablePath);
		if (AppLocation.Substring(AppLocation.Length - 1) != "\\")
		{
			AppLocation += "\\";
		}
		if (FontFace == "")
		{
			FontFace = CommonMethods.IniReadValue(AppLocation + "OptionSet.ini", "Digital", "XlsFont");
		}
	}

	public int ExecuteExp()
	{
		if (!enableOldExportExcel)
		{
			if (FExpType == "BUD")
			{
				reportManager = new BudgetReportManager(outputAliasAsItemName);
			}
			else if (FExpType == "BID")
			{
				reportManager = new BidReportManager();
			}
		}
		BidFooterWithData = $"投標廠商：{vendorName}\u3000\u3000\u3000\u3000\u3000\u3000\u3000[印]\u3000\u3000\u3000\u3000\u3000\u3000\u3000\u3000\u3000\u3000負責人：{vendorOwner}\u3000\u3000\u3000\u3000\u3000[印]";
		License license = new License();
		license.SetLicense("Aspose.Custom.lic");
		myExcel = new Excel();
		int status = 0;
		iCurrSheet = 0;
		decItemQty = 3;
		decItemCost = 0;
		decItemAmt = 0;
		decAnalQty = 3;
		decAnalCost = 2;
		decAnalAmt = 2;
		SumDec = decItemAmt;
		Archnowledge.Pcces.DomainModule.General.PubDecimal pubDecimal = new Archnowledge.Pcces.DomainModule.General.PubDecimal();
		DataSet dsPubDecimal = pubDecimal.GetPubDecimal(FProjectCode);
		if (dsPubDecimal.Tables[0].Rows.Count > 0)
		{
			DataRow drPubDecimal = dsPubDecimal.Tables[0].Rows[0];
			decItemQty = ArchConvert.Obj2Int(drPubDecimal["itemQty"]);
			decItemCost = ArchConvert.Obj2Int(drPubDecimal["itemCost"]);
			decItemAmt = ArchConvert.Obj2Int(drPubDecimal["itemAmt"]);
			decAnalQty = ArchConvert.Obj2Int(drPubDecimal["analysisQty"]);
			decAnalCost = ArchConvert.Obj2Int(drPubDecimal["analysisCost"]);
			decAnalAmt = ArchConvert.Obj2Int(drPubDecimal["analysisAmt"]);
			enableItemAmt2 = ArchConvert.Obj2Bool(drPubDecimal["EnableItemAmt2"]);
		}
		F_TotalProgPos = 0;
		F_TotalProgMax = 2;
		F_TotalProgMin = 0;
		if (FIsShowCost && FExpType.ToUpper() == "BUD")
		{
			F_TotalProgMax++;
		}
		if (FIsShowAnalysis)
		{
			F_TotalProgMax++;
		}
		Application.DoEvents();
		bool IsFillHintFormula = true;
		if ((FIsShowCost && FExpType.ToUpper() == "BUD") || F_IsPrintSummaryInBID)
		{
			F_ExpStatus = "【總表】資料整理中...[Formatted]";
			if (F_ExportSheets.Substring(0, 1) == "1")
			{
				Application.DoEvents();
				if (FExpType.ToUpper() != "BUD" && FExpType.ToUpper() != "BID" && FExpType.ToUpper() != "SUB")
				{
					if (FExpType.ToUpper() != "IVO")
					{
						status = SUB_Summary();
					}
					else
					{
						IVO_SummaryIssue();
						status = IVO_Summary();
					}
				}
				else
				{
					status = BDGT_Summary();
				}
			}
			if (status != 0)
			{
				return status;
			}
			F_TotalProgPos++;
			Application.DoEvents();
		}
		if (FIsShowAnalysis)
		{
			F_ExpStatus = "【單價分析表】資料整理中...[Formatted]";
			if (F_ExportSheets.Substring(2, 1) == "1")
			{
				if (chkCnE)
				{
					Application.DoEvents();
					status = BDGT_Analysis_CnE();
				}
				else
				{
					Application.DoEvents();
					status = ((FExpType.ToUpper() != "BUD" && FExpType.ToUpper() != "BID" && FExpType.ToUpper() != "SUB") ? SUB_Analysis2() : ((!F_IsAnaHalfPage) ? BDGT_Analysis() : BDGT_Analysis2()));
				}
			}
			if (status != 0)
			{
				return status;
			}
			F_TotalProgPos++;
			Application.DoEvents();
		}
		F_ExpStatus = "【詳細表】資料整理中...[Formatted]";
		if (F_ExportSheets.Substring(1, 1) == "1")
		{
			Application.DoEvents();
			status = ((!(FExpType.ToUpper() != "BUD") || !(FExpType.ToUpper() != "BID") || !(FExpType.ToUpper() != "SUB")) ? BDGT_Items() : SUB_Items());
		}
		else
		{
			IsFillHintFormula = false;
		}
		if (status != 0)
		{
			return status;
		}
		F_TotalProgPos++;
		Application.DoEvents();
		if (FExpType != "IVO" && FExpType != "SUBCLO" && FExpType != "SUBFNL")
		{
			F_ExpStatus = "【資源統計表】資料整理中...[Formatted]";
			if (F_ExportSheets.Substring(3, 1) == "1")
			{
				Application.DoEvents();
				status = BDGT_MrsBase();
			}
			else
			{
				IsFillHintFormula = false;
			}
			if (status != 0)
			{
				return status;
			}
			F_TotalProgPos = F_TotalProgMax;
			Application.DoEvents();
		}
		if (IsFillHintFormula && !FIsShowCost && FExpType == "BUD")
		{
			int iStyleIndex = myExcel.Styles.Add();
			Style StyleV1 = myExcel.Styles[iStyleIndex];
			StyleV1.Font.Color = Color.Red;
			StyleV1.IsTextWrapped = false;
			StyleV1.Borders[BorderType.TopBorder].LineStyle = CellBorderType.Thin;
			StyleV1.Borders[BorderType.BottomBorder].LineStyle = CellBorderType.None;
			if (chkCnE && BDGT_Row % 40 == 7)
			{
				StyleV1.Borders[BorderType.LeftBorder].LineStyle = CellBorderType.None;
				StyleV1.Borders[BorderType.RightBorder].LineStyle = CellBorderType.None;
			}
			else
			{
				StyleV1.Borders[BorderType.LeftBorder].LineStyle = CellBorderType.Thin;
				StyleV1.Borders[BorderType.RightBorder].LineStyle = CellBorderType.Thin;
			}
			iStyleIndex = myExcel.Styles.Add();
			Style StyleV1ForResource = myExcel.Styles[iStyleIndex];
			StyleV1ForResource.Font.Color = Color.Red;
			StyleV1ForResource.IsTextWrapped = false;
			StyleV1ForResource.Borders[BorderType.TopBorder].LineStyle = CellBorderType.Thin;
			StyleV1ForResource.Borders[BorderType.BottomBorder].LineStyle = CellBorderType.None;
			if (chkCnE && RESOURCE_Row % 40 == 8)
			{
				StyleV1ForResource.Borders[BorderType.LeftBorder].LineStyle = CellBorderType.None;
				StyleV1ForResource.Borders[BorderType.RightBorder].LineStyle = CellBorderType.None;
			}
			else
			{
				StyleV1ForResource.Borders[BorderType.LeftBorder].LineStyle = CellBorderType.Thin;
				StyleV1ForResource.Borders[BorderType.RightBorder].LineStyle = CellBorderType.Thin;
			}
			iStyleIndex = myExcel.Styles.Add();
			Style StyleV2 = myExcel.Styles[iStyleIndex];
			StyleV2.Font.Color = Color.Red;
			StyleV2.IsTextWrapped = false;
			StyleV2.Borders[BorderType.TopBorder].LineStyle = CellBorderType.Thin;
			StyleV2.Borders[BorderType.BottomBorder].LineStyle = CellBorderType.Thin;
			StyleV2.Borders[BorderType.LeftBorder].LineStyle = CellBorderType.Thin;
			StyleV2.Borders[BorderType.RightBorder].LineStyle = CellBorderType.Thin;
			if (chkCnE)
			{
				if (!IsBlankBudget)
				{
					myExcel.Worksheets["標單詳細表"].Cells["B" + Convert.ToString(BDGT_Row + 1 + 1)].Formula = "=If(F" + Convert.ToString(BDGT_Row + 1) + "<>標單資源統計表!F" + Convert.ToString(RESOURCE_Row + 1) + ",\"此頁的總價(總計)與 [標單資源統計表] 的【總價(總計)金額】不符\",\"\")";
					myExcel.Worksheets["標單詳細表"].Cells["B" + Convert.ToString(BDGT_Row + 1 + 1)].Style = StyleV1;
					myExcel.Worksheets["標單資源統計表"].Cells["B" + Convert.ToString(RESOURCE_Row + 1 + 1)].Formula = "=If(F" + Convert.ToString(RESOURCE_Row + 1) + "<>標單詳細表!F" + Convert.ToString(BDGT_Row + 1) + ",\"此頁的總價(總計)與 [標單詳細表] 的【總價(總計)金額】不符\",\"\")";
					myExcel.Worksheets["標單資源統計表"].Cells["B" + Convert.ToString(RESOURCE_Row + 1 + 1)].Style = StyleV1ForResource;
				}
			}
			else
			{
				if (BDGT_Row != 0 && !IsBlankBudget)
				{
					myExcel.Worksheets["標單詳細表"].Cells["G" + Convert.ToString(BDGT_Row)].Formula = "=If(F" + Convert.ToString(BDGT_Row) + "<>標單資源統計表!F" + Convert.ToString(RESOURCE_Row) + ",\"此頁的總價(總計)與 [標單資源統計表] 的【總價(總計)金額】不符\",\"\")";
					myExcel.Worksheets["標單詳細表"].Cells["G" + Convert.ToString(BDGT_Row)].Style = StyleV2;
				}
				if (RESOURCE_Row != 0 && !IsBlankBudget)
				{
					myExcel.Worksheets["標單資源統計表"].Cells["C" + Convert.ToString(RESOURCE_Row)].Formula = "=If(F" + Convert.ToString(RESOURCE_Row) + "<>標單詳細表!F" + Convert.ToString(BDGT_Row) + ",\"此頁的總價(總計)與 [標單詳細表] 的【總價(總計)金額】不符\",\"\")";
					myExcel.Worksheets["標單資源統計表"].Cells["C" + Convert.ToString(RESOURCE_Row)].Style = StyleV2;
				}
			}
		}
		myExcel.Save(FFileName);
		myExcel = null;
		return status;
	}

