				myRange.Style = myStypeSum_EmptyA;
				myRange = myCells.CreateRange("G" + Convert.ToString(i + 9), "G" + Convert.ToString(i + 9));
				myRange.Style = myStypeSum_EmptyA;
				myRange = myCells.CreateRange("H" + Convert.ToString(i + 9), "H" + Convert.ToString(i + 9));
				myRange.Style = myStypeSum_Empty2;
			}
			if ((TotalRowCount >= 30 && !chkCnE) || (TotalRowCount >= 40 && chkCnE))
			{
