			mySheet.Cells.Merge(i + 9 + rows.Length - 1, 1, 1, 4);
			myRange.RowHeight = 19.5;
			myRange = myCells.CreateRange("A" + Convert.ToString(i + 9 + rows.Length), "H" + Convert.ToString(i + 9 + rows.Length));
