			myStypeSum_Empty3.Borders[BorderType.BottomBorder].LineStyle = CellBorderType.Thin;
			myStypeSum_Empty3.Borders[BorderType.LeftBorder].LineStyle = CellBorderType.Thin;
			myStypeSum_Empty3.Borders[BorderType.RightBorder].LineStyle = CellBorderType.Thin;
