			myStyleSum_LockAmt1.Font.Name = FontFace;
			myStyleSum_LockAmt1.IsTextWrapped = false;
			myStyleSum_LockAmt1.HorizontalAlignment = TextAlignmentType.Left;
			myStyleSum_LockAmt1.ShrinkToFit = F_AutoShrink;
			myStyleSum_LockAmt1.ForegroundColor = ((!FIsShowCost) ? Color.FromArgb(255, 255, 153) : Color.Transparent);
			if (!FIsShowCost)
			{
				myStyleSum_LockAmt1.Pattern = BackgroundType.Solid;
			}
			myStyleSum_LockAmt1.Custom = ((decItemAmt > 0) ? ("_-* #,##0." + Replicate("0", decItemAmt) + "_-;-* #,##0." + Replicate("0", decItemAmt) + "_-;_-* \"-\"_-;_-@_-") : "_-* #,##0_-;-* #,##0_-;_-* \"-\"_-;_-@_-");
			myStyleSum_LockAmt1.Borders[BorderType.TopBorder].LineStyle = CellBorderType.Thin;
			myStyleSum_LockAmt1.Borders[BorderType.BottomBorder].LineStyle = CellBorderType.Thin;
			myStyleSum_LockAmt1.Borders[BorderType.LeftBorder].LineStyle = CellBorderType.Thin;
			myStyleSum_LockAmt1.Borders[BorderType.RightBorder].LineStyle = CellBorderType.Thin;
			iStyleIndex = myExcel.Styles.Add();
			Style myStyleSum_LockAmt2 = myExcel.Styles[iStyleIndex];
			myStyleSum_LockAmt2.IsLocked = false;
			myStyleSum_LockAmt2.IsFormulaHidden = false;
			myStyleSum_LockAmt2.Font.Size = (short)(chkCnE ? 8 : 8);
			myStyleSum_LockAmt2.Font.IsBold = false;
			myStyleSum_LockAmt2.Font.Name = FontFace;
			myStyleSum_LockAmt2.IsTextWrapped = false;
