			}
			myStyleSum_LockAmt2.Custom = ((decItemAmt > 0) ? ("_-* #,##0." + Replicate("0", decItemAmt) + "_-;-* #,##0." + Replicate("0", decItemAmt) + "_-;_-* \"-\"_-;_-@_-") : "_-* #,##0_-;-* #,##0_-;_-* \"-\"_-;_-@_-");
			myStyleSum_LockAmt2.Borders[BorderType.TopBorder].LineStyle = CellBorderType.None;
			myStyleSum_LockAmt2.Borders[BorderType.BottomBorder].LineStyle = CellBorderType.None;
			myStyleSum_LockAmt2.Borders[BorderType.LeftBorder].LineStyle = CellBorderType.Thin;
			myStyleSum_LockAmt2.Borders[BorderType.RightBorder].LineStyle = CellBorderType.Thin;
			iStyleIndex = myExcel.Styles.Add();
			Style myStyleSum_LockAmtBtm = myExcel.Styles[iStyleIndex];
			myStyleSum_LockAmtBtm.IsLocked = false;
			myStyleSum_LockAmtBtm.IsFormulaHidden = false;
			myStyleSum_LockAmtBtm.Font.Size = (short)(chkCnE ? 8 : 8);
			myStyleSum_LockAmtBtm.Font.IsBold = false;
			myStyleSum_LockAmtBtm.Font.Name = FontFace;
			myStyleSum_LockAmtBtm.IsTextWrapped = false;
			myStyleSum_LockAmtBtm.HorizontalAlignment = TextAlignmentType.Left;
			myStyleSum_LockAmtBtm.ShrinkToFit = F_AutoShrink;
			myStyleSum_LockAmtBtm.ForegroundColor = ((!FIsShowCost) ? Color.FromArgb(255, 255, 153) : Color.Transparent);
			if (!FIsShowCost)
			{
				myStyleSum_LockAmtBtm.Pattern = BackgroundType.Solid;
			}
			myStyleSum_LockAmtBtm.Custom = ((decItemAmt > 0) ? ("_-* #,##0." + Replicate("0", decItemAmt) + "_-;-* #,##0." + Replicate("0", decItemAmt) + "_-;_-* \"-\"_-;_-@_-") : "_-* #,##0_-;-* #,##0_-;_-* \"-\"_-;_-@_-");
			myStyleSum_LockAmtBtm.Borders[BorderType.TopBorder].LineStyle = CellBorderType.None;
			myStyleSum_LockAmtBtm.Borders[BorderType.BottomBorder].LineStyle = CellBorderType.Thin;
			myStyleSum_LockAmtBtm.Borders[BorderType.LeftBorder].LineStyle = CellBorderType.Thin;
			myStyleSum_LockAmtBtm.Borders[BorderType.RightBorder].LineStyle = CellBorderType.Thin;
			iStyleIndex = myExcel.Styles.Add();
			Style myStyleSum_LockAmtBtm2 = myExcel.Styles[iStyleIndex];
			myStyleSum_LockAmtBtm2.IsLocked = false;
			myStyleSum_LockAmtBtm2.IsFormulaHidden = false;
			myStyleSum_LockAmtBtm2.Font.Size = (short)(chkCnE ? 8 : 8);
			myStyleSum_LockAmtBtm2.Font.IsBold = false;
			myStyleSum_LockAmtBtm2.Font.Name = FontFace;
			myStyleSum_LockAmtBtm2.IsTextWrapped = false;
			myStyleSum_LockAmtBtm2.HorizontalAlignment = TextAlignmentType.Left;
			myStyleSum_LockAmtBtm2.ShrinkToFit = F_AutoShrink;
			myStyleSum_LockAmtBtm2.ForegroundColor = ((!FIsShowCost) ? Color.FromArgb(255, 255, 153) : Color.Transparent);
			if (!FIsShowCost)
			{
				myStyleSum_LockAmtBtm2.Pattern = BackgroundType.Solid;
			}
			myStyleSum_LockAmtBtm2.Custom = ((decItemAmt > 0) ? ("_-* #,##0." + Replicate("0", decItemAmt) + "_-;-* #,##0." + Replicate("0", decItemAmt) + "_-;_-* \"-\"_-;_-@_-") : "_-* #,##0_-;-* #,##0_-;_-* \"-\"_-;_-@_-");
			myStyleSum_LockAmtBtm2.Borders[BorderType.TopBorder].LineStyle = CellBorderType.Thin;
			myStyleSum_LockAmtBtm2.Borders[BorderType.BottomBorder].LineStyle = CellBorderType.Thin;
			myStyleSum_LockAmtBtm2.Borders[BorderType.LeftBorder].LineStyle = CellBorderType.Thin;
			myStyleSum_LockAmtBtm2.Borders[BorderType.RightBorder].LineStyle = CellBorderType.Thin;
			for (int kk = 9; kk <= 9 + rows.Length + Remains - 1; kk++)
			{
				int iVal = PubTools.Str2Int(mySheet.Cells["H" + Convert.ToString(kk)].StringValue);
				myRange = myCells.CreateRange("F" + Convert.ToString(kk), "F" + Convert.ToString(kk));
				if (kk < 9 + rows.Length + Remains - 1)
				{
					if (chkCnE)
					{
						myRange.Style = ((kk % 2 == 1) ? myStyleSum_LockAmt1 : myStyleSum_LockAmtBtm);
					}
					else
					{
						myRange.Style = ((iVal > 1) ? myStyleSum_LockAmt2 : myStyleSum_LockAmt1);
					}
				}
				else if (chkCnE)
				{
					myRange.Style = myStyleSum_LockAmtBtm;
				}
				else if (PubTools.Str2Int(mySheet.Cells["H" + Convert.ToString(kk - 1)].StringValue) > 1)
				{
					myRange.Style = myStyleSum_LockAmtBtm;
				}
				else
				{
					myRange.Style = myStyleSum_LockAmtBtm2;
				}
			}
		}
		for (int kk = 9; kk <= 9 + rows.Length + Remains; kk++)
		{
			mySheet.Cells["I" + Convert.ToString(kk)].PutValue("");
			mySheet.Cells["J" + Convert.ToString(kk)].PutValue("");
		}
		ProtectSheet(mySheet);
		F_ProgPos = F_ProgMax;
		Application.DoEvents();
		return 0;
	}

	private int IVO_Summary()
	{
		string AlterExtraStr = "[預算]";
		int TotalRowCount = 0;
		int Remains = 0;
		Range myRange = null;
		int iStyleIndex = 0;
		myTable = Sum_Rep();
		li_len = 36;
		ExtraWork(1);
		DataRow[] rows = NewDT.Select();
		F_ExpStatus = "【總表】EXCEL輸出中...[Formatted]";
		Application.DoEvents();
		if (iCurrSheet > 0)
		{
			myExcel.Worksheets.Add();
		}
		Worksheet mySheet = myExcel.Worksheets[iCurrSheet];
		Cells myCells = mySheet.Cells;
		mySheet.Name = "預算總表";
		iCurrSheet++;
		if (FExpType == "SUBCHG")
		{
			mySheet.Name = "契約變更總表";
			AlterExtraStr = "[契約變更]";
		}
		if (FExpType == "IVO")
		{
			mySheet.Name = "估驗計價總表";
			AlterExtraStr = "[計價]";
		}
		if (FExpType == "SUBCLO")
		{
			mySheet.Name = "結算總表";
			AlterExtraStr = "[結算]";
		}
		if (FExpType == "SUBFNL")
		{
			mySheet.Name = "決算總表";
			AlterExtraStr = "[決算]";
		}
		try
		{
			mySheet.PageSetup.SetHeader(2, chkCnE ? ('\r' + "&\"" + FontFace + ",標準\"&10 第 &P 頁 共 &N 頁" + '\n' + "&10 Sheet No. &P of &N ") : ("&\"" + FontFace + ",標準\"&10 第 &P 頁 共 &N 頁"));
			if (chkCnE)
			{
				string sFootDate = "日期：" + (F_PrintDate.Year - 1911) + "年" + F_PrintDate.Month.ToString().PadLeft(2, '0') + "月" + F_PrintDate.Day.ToString().PadLeft(2, '0');
				if (!F_IsShowDate)
				{
					sFootDate = "日期：";
				}
				mySheet.PageSetup.SetFooter(0, "&\"" + FontFace + ",標準\"&10  " + F_CnE_CTail.Trim() + "".PadLeft(20, ' ') + sFootDate + '\n' + "  " + F_CnE_ETail.Trim() + "".PadLeft(18, ' ') + "Date");
			}
			else
			{
				FFooter = ((FFooter.Trim() != "") ? FFooter : "編製");
				mySheet.PageSetup.SetFooter(0, "&\"" + FontFace + ",標準\"&10" + FFooter);
			}
		}
		catch (Exception ex)
		{
			CommonMethods.LogFile("Pcces46", "M", "Conversion.cs" + ex.Message);
			return 1;
		}
		mySheet.PageSetup.LeftMargin = 1.0;
		mySheet.PageSetup.TopMargin = (chkCnE ? 1.0 : 1.5);
		mySheet.PageSetup.BottomMargin = (chkCnE ? 1.5 : 3.0);
		mySheet.PageSetup.RightMargin = 0.0;
		mySheet.PageSetup.HeaderMargin = (chkCnE ? 2.5 : 2.5);
		mySheet.PageSetup.FooterMargin = (chkCnE ? 2.0 : 1.5);
		mySheet.PageSetup.CenterHorizontally = true;
		mySheet.PageSetup.Zoom = (chkCnE ? 90 : 70);
		mySheet.Cells.SetColumnWidth(0, 11.0);
		mySheet.Cells.SetColumnWidth(1, 37.0);
		mySheet.Cells.SetColumnWidth(2, chkCnE ? 8.0 : 6.0);
		mySheet.Cells.SetColumnWidth(3, 10.0);
		mySheet.Cells.SetColumnWidth(4, chkCnE ? 11.0 : 9.5);
		mySheet.Cells.SetColumnWidth(5, 12.03);
		mySheet.Cells.SetColumnWidth(6, 12.0);
		mySheet.Cells.SetColumnWidth(7, 12.0);
		mySheet.Cells.SetColumnWidth(8, 12.0);
		mySheet.Cells.SetColumnWidth(9, 12.0);
		mySheet.Cells.SetColumnWidth(10, 12.0);
		mySheet.Cells.SetColumnWidth(11, 12.0);
		mySheet.Cells.SetColumnWidth(12, 12.5);
		iStyleIndex = myExcel.Styles.Add();
		Style myStypeHeader = myExcel.Styles[iStyleIndex];
		myStypeHeader.Font.Size = (short)(chkCnE ? 14 : 16);
		myStypeHeader.Font.IsBold = true;
		myStypeHeader.Font.Name = FontFace;
		myStypeHeader.HorizontalAlignment = TextAlignmentType.Center;
		myStypeHeader.VerticalAlignment = TextAlignmentType.Center;
		myStypeHeader.IsTextWrapped = true;
		iStyleIndex = myExcel.Styles.Add();
		Style myStyleDet_Header1 = myExcel.Styles[iStyleIndex];
		myStyleDet_Header1.Font.Size = (short)(chkCnE ? 12 : 16);
		myStyleDet_Header1.Font.IsBold = true;
		myStyleDet_Header1.Font.Name = FontFace;
		myStyleDet_Header1.HorizontalAlignment = TextAlignmentType.Center;
		myStyleDet_Header1.VerticalAlignment = TextAlignmentType.Center;
		myStyleDet_Header1.IsTextWrapped = true;
		myRange = myCells.CreateRange("A1", "M1");
		mySheet.Cells.Merge(0, 0, 1, 13);
		mySheet.Cells["A1"].PutValue(chkCnE ? (FDeptName + "\n" + FDeptEName) : FDeptName);
		if (FDeptEName.Length > 56)
		{
			myRange.Style = myStyleDet_Header1;
		}
		else
		{
