			{
				int iVal = PubTools.Str2Int(mySheet.Cells["H" + Convert.ToString(kk)].StringValue);
				myRange = myCells.CreateRange("F" + Convert.ToString(kk), "F" + Convert.ToString(kk));
				if (kk < 9 + rows.Length + Remains - 1)
				{
					if (chkCnE)
					{
						myRange.Style = ((kk % 2 == 1) ? myStyleSum_LockAmt1 : myStyleSum_LockAmtBtm);
					}
					else
					{
						myRange.Style = ((iVal > 1) ? myStyleSum_LockAmt2 : myStyleSum_LockAmt1);
					}
				}
				else if (chkCnE)
				{
					myRange.Style = myStyleSum_LockAmtBtm;
				}
				else if (PubTools.Str2Int(mySheet.Cells["H" + Convert.ToString(kk - 1)].StringValue) > 1)
				{
					myRange.Style = myStyleSum_LockAmtBtm;
				}
				else
				{
					myRange.Style = myStyleSum_LockAmtBtm2;
				}
			}
		}
		F_ProgPos = F_ProgMax;
		Application.DoEvents();
		return 0;
	}

