	private int FillProjectDescription(Worksheet worksheet, int LineCountRemain, int startRowIndex, string sBUD_TYPE, bool FIsShowCost, string FExpType)
	{
		int styleIndex = myExcel.Styles.Add();
		Style styleBlankCell = myExcel.Styles[styleIndex];
		styleBlankCell.Borders[BorderType.TopBorder].LineStyle = CellBorderType.Thin;
		styleBlankCell.Borders[BorderType.BottomBorder].LineStyle = CellBorderType.Thin;
