		styleLeftRightBorder.Font.Size = 10;
		styleLeftRightBorder.Font.Name = FontFace;
		styleLeftRightBorder.IndentLevel = 1;
		styleLeftRightBorder.HorizontalAlignment = TextAlignmentType.Left;
		styleLeftRightBorder.VerticalAlignment = TextAlignmentType.Bottom;
		styleLeftRightBorder.IsTextWrapped = false;
		styleLeftRightBorder.Borders[BorderType.LeftBorder].LineStyle = CellBorderType.Thin;
		styleLeftRightBorder.Borders[BorderType.RightBorder].LineStyle = CellBorderType.Thin;
		styleIndex = myExcel.Styles.Add();
		Style styleLeftRightBottomBorder = myExcel.Styles[styleIndex];
		styleLeftRightBottomBorder.Font.Size = 10;
		styleLeftRightBottomBorder.Font.Name = FontFace;
		styleLeftRightBottomBorder.IndentLevel = 1;
		styleLeftRightBottomBorder.HorizontalAlignment = TextAlignmentType.Left;
		styleLeftRightBottomBorder.VerticalAlignment = TextAlignmentType.Bottom;
		styleLeftRightBottomBorder.IsTextWrapped = false;
