		styleLeftRightBottomBorder.Borders[BorderType.RightBorder].LineStyle = CellBorderType.Thin;
		styleLeftRightBottomBorder.Borders[BorderType.BottomBorder].LineStyle = CellBorderType.Thin;
		styleIndex = myExcel.Styles.Add();
		Style styleDescriptionText = myExcel.Styles[styleIndex];
		styleDescriptionText.Font.Size = 10;
		styleDescriptionText.Font.Name = FontFace;
		styleDescriptionText.HorizontalAlignment = TextAlignmentType.Center;
		styleDescriptionText.VerticalAlignment = TextAlignmentType.Bottom;
		styleDescriptionText.IsTextWrapped = false;
		styleDescriptionText.Borders[BorderType.TopBorder].LineStyle = CellBorderType.Thin;
		styleDescriptionText.Borders[BorderType.LeftBorder].LineStyle = CellBorderType.Thin;
		styleDescriptionText.Borders[BorderType.RightBorder].LineStyle = CellBorderType.Thin;
		styleDescriptionText.Borders[BorderType.BottomBorder].LineStyle = CellBorderType.Thin;
		DBClass DBCLS = new DBClass();
		DBCLS._FS_UserID = UserID;
		DataTable DT_BudProject = DBCLS.GetUserDefine("Select IsNull(correctRate,0) as correctRate, IsNull(weightedCorrectRate,0) as weightedCorrectRate, IsNull(confirmRate,0) as confirmRate from budProject Where projectCode='" + FProjectCode + "'");
		string CodeRateStr = "";
		if (!(sBUD_TYPE == "CNT") && (FIsShowCost || !(FExpType == "BUD")) && (!FIsShowCost || !(FExpType == "BID")) && DT_BudProject.Rows.Count > 0)
		{
			CodeRateStr = string.Format("本專案編碼正確率{0:N2}%;綱要編碼正確率{1:N2}%\u3000\u3000\u3000\u3000\u3000 ", DT_BudProject.Rows[0]["correctRate"], DT_BudProject.Rows[0]["confirmRate"]);
		}
		Cells sheetCells = worksheet.Cells;
		for (int index = 0; index <= 6; index++)
		{
			Range cellRange = sheetCells.CreateRange(startRowIndex - 1, index, 1, 1);
			cellRange.Style = styleBlankCell;
			cellRange.RowHeight = 19.5;
		}
		if (DetailListPrintProjectDescription)
		{
			sheetCells[startRowIndex - 1, 0].PutValue("註");
		}
		sheetCells[startRowIndex - 1, 0].Style = styleDescriptionText;
		string[] projectDescriptions = null;
		CodeRateStr = MakeOneLineStr(CodeRateStr, 100);
		if (DetailListPrintProjectDescription && F_ShowCodeCorrectRate)
		{
			projectDescriptions = StringHandler.BreakLines(CodeRateStr + "" + projectDescription, 100);
		}
		else if (DetailListPrintProjectDescription)
		{
			projectDescriptions = StringHandler.BreakLines(projectDescription, 100);
		}
		else if (F_ShowCodeCorrectRate)
		{
			projectDescriptions = StringHandler.BreakLines(CodeRateStr, 100);
		}
		int DescriptionLineCount = projectDescriptions.Length;
		int DescriptionCapacityLineCount = LineCountRemain - 1;
		if (DescriptionLineCount > DescriptionCapacityLineCount)
		{
			DescriptionCapacityLineCount = (int)Math.Ceiling((double)(DescriptionLineCount - DescriptionCapacityLineCount) * 1.0 / 30.0) * 30 + DescriptionCapacityLineCount;
		}
		bool isLastRow = false;
		for (int index = 1; index <= DescriptionCapacityLineCount; index++)
		{
			isLastRow = (startRowIndex + index - 38) % 30 == 0;
			worksheet.Cells.Merge(startRowIndex + index - 1, 0, 1, 7);
			Range rangeProjectDescription = sheetCells.CreateRange("A" + (startRowIndex + index), "G" + (startRowIndex + index));
			rangeProjectDescription.Style = (isLastRow ? styleLeftRightBottomBorder : styleLeftRightBorder);
			rangeProjectDescription.RowHeight = 19.5;
			if (index <= DescriptionLineCount)
			{
				worksheet.Cells["A" + (startRowIndex + index)].PutValue(projectDescriptions[index - 1]);
			}
			if (isLastRow && index != DescriptionCapacityLineCount)
			{
				worksheet.HPageBreaks.Add("A" + (startRowIndex + index + 1));
			}
		}
		return startRowIndex + DescriptionCapacityLineCount;
	}

