	private string MakeOneLineStr(string CodeRateStr, int ProjectDescriptionWordCountPerLine)
	{
		char[] myChars = CodeRateStr.ToCharArray();
		int chars_count = 0;
		string sTemp = "";
		for (int i = 0; i < myChars.Length; i++)
		{
			chars_count = ((myChars[i] <= 'ÿ') ? (chars_count + 1) : (chars_count + 2));
			sTemp += myChars[i];
		}
		return CodeRateStr + "".PadLeft(ProjectDescriptionWordCountPerLine - chars_count - 1, ' ');
	}

