			for (int kk = 9; kk <= iDoneRows; kk++)
			{
				int iVal = PubTools.Str2Int(mySheet.Cells["H" + Convert.ToString(kk)].StringValue);
				myRange = myCells.CreateRange("E" + Convert.ToString(kk), "E" + Convert.ToString(kk));
				if (kk < iDoneRows)
				{
					if (chkCnE)
					{
						myRange.Style = ((kk % 2 == 1) ? myStyleDet_LockCost1 : myStyleDet_LockCostBtm);
					}
					else if (iVal > 1)
					{
						if (mySheet.Cells["K" + Convert.ToString(kk)].StringValue == "PB")
						{
							myRange.Style = myStyleDet_LockCostBtm;
						}
						else
						{
							myRange.Style = myStyleDet_LockCost2;
						}
					}
					else if (mySheet.Cells["K" + Convert.ToString(kk)].StringValue == "PB")
					{
						myRange.Style = myStyleDet_LockCostBtm2;
					}
					else
					{
						myRange.Style = myStyleDet_LockCost1;
					}
				}
				else if (chkCnE)
				{
					myRange.Style = myStyleDet_LockCostBtm;
				}
				else if (PubTools.Str2Int(mySheet.Cells["H" + Convert.ToString(kk - 1)].StringValue) > 1)
				{
					myRange.Style = myStyleDet_LockCostBtm;
				}
				else
				{
					myRange.Style = myStyleDet_LockCostBtm2;
				}
				myRange = myCells.CreateRange("F" + Convert.ToString(kk), "F" + Convert.ToString(kk));
