						{
							myRange.Style = myStyleDet_LockAmtBtm;
						}
						else
						{
							myRange.Style = myStyleDet_LockAmt2;
						}
					}
					else if (mySheet.Cells["K" + Convert.ToString(kk)].StringValue == "PB")
					{
						myRange.Style = myStyleDet_LockAmtBtm2;
					}
					else
					{
						myRange.Style = myStyleDet_LockAmt1;
					}
				}
				else if (chkCnE)
				{
