				}
				else
				{
					myRange.Style = myStyleDet_LockAmtBtm2;
				}
			}
		}
		for (int kk = 9; kk <= 9 + rows.Count + iBlankRows; kk++)
		{
			if (FExpType != "IVO" && FExpType != "SUBCLO" && FExpType != "SUBFNL")
			{
				mySheet.Cells["K" + Convert.ToString(kk)].PutValue("");
				mySheet.Cells["L" + Convert.ToString(kk)].PutValue("");
			}
			else
			{
				mySheet.Cells["N" + Convert.ToString(kk)].PutValue("");
				mySheet.Cells["O" + Convert.ToString(kk)].PutValue("");
			}
		}
		ProtectSheet(mySheet);
		F_ProgPos = F_ProgMax;
		Application.DoEvents();
		return 0;
