		{
			if (F_IsPrice)
			{
				myTable = reportManager.GetResourceList(FProjectCode, FIsShowAnalysis, out negativeNumberGenerated).Tables[0];
				if (negativeNumberGenerated)
				{
					warningMessage = "依『招標增列文件作業要點』規定，詳細表與資源統計表總價金額必須一致，本預算有因取位而需四捨五入致產生誤差值，但專案工項之 W 類雜項複價不夠攤提誤差值，請於單價分析項增加 W 類工項或增加其公式計算 % 值，以利系統自動以 W 類項目平衡誤差值。";
				}
			}
			else
			{
				myTable = reportManager.GetRequestBidResourceList(FProjectCode, FIsShowAnalysis).Tables[0];
				ArrayList Log_aArr = new ArrayList();
				Log_aArr.Add(UserID);
				Log_aArr.Add("預算編輯--讀取目前資源統計表");
				ModifyDB StdCom2 = new ModifyDB(FProjectCode, Log_aArr);
				DataTable ldt_IsBid = StdCom2.DBList("SELECT sNo, IsBid, IsFormulaChangeKind, FormulaNewName From budPageBreak WHERE ProjectCode='" + FProjectCode + "' AND (IsBid='N' OR IsFormulaChangeKind='Y')");
				ldt_IsBid.PrimaryKey = new DataColumn[1] { ldt_IsBid.Columns["sNo"] };
				if (ldt_IsBid.Rows.Count > 0)
				{
					for (int j = 0; j < myTable.Rows.Count; j++)
					{
						string theSNO = myTable.Rows[j]["itemSNo"].ToString().Trim();
						DataRow dr = ldt_IsBid.Rows.Find(theSNO);
						if (dr == null)
						{
							continue;
						}
						if (dr["IsBid"] != null && dr["IsBid"].ToString().ToUpper().Trim() == "N")
						{
							myTable.Rows[j]["IsBid"] = 'N';
						}
						else if ("FSU".IndexOf(myTable.Rows[j]["kind"].ToString().ToUpper().Trim()) > -1 && dr["IsFormulaChangeKind"] != null && dr["IsFormulaChangeKind"].ToString().ToUpper().Trim() == "Y")
						{
							myTable.Rows[j]["kind"] = "L";
							if (dr["FormulaNewName"] != null && dr["FormulaNewName"].ToString() != string.Empty)
							{
								myTable.Rows[j]["cName"] = dr["FormulaNewName"].ToString().Trim();
							}
						}
					}
					myTable.AcceptChanges();
				}
			}
		}
		else
		{
			myTable = Resource_Rep();
		}
		li_len = 34;
		ExtraWork(4);
		DataView rows = NewDT.DefaultView;
		F_ExpStatus = "【資源統計表】EXCEL輸出中...[Formatted]";
