					myStyleDet_PageFooder.Font.Size = 10;
					myStyleDet_PageFooder.Font.IsBold = false;
					myStyleDet_PageFooder.Font.Name = FontFace;
					myStyleDet_PageFooder.HorizontalAlignment = TextAlignmentType.Left;
					myStyleDet_PageFooder.ShrinkToFit = F_AutoShrink;
					myStyleDet_PageFooder.Custom = "@";
					if (bidFooterPrintVendorInfo)
					{
						mySheet.Cells.Merge(iStartRow, 1, 1, 2);
						mySheet.Cells.Merge(iStartRow, 3, 1, 3);
					}
					mySheet.Cells["B" + Convert.ToString(iStartRow + 1)].PutValue("投標廠商：" + (bidFooterPrintVendorInfo ? vendorName : string.Empty));
					mySheet.Cells["D" + Convert.ToString(iStartRow + 1)].PutValue("負責人：" + (bidFooterPrintVendorInfo ? vendorOwner : string.Empty));
					myRange = myCells.CreateRange("A" + Convert.ToString(iStartRow + 1), "G" + Convert.ToString(iStartRow + 1));
					myRange.Style = myStyleDet_PageFooder;
					if (myPageLength == "L")
					{
						iStartRow += 2;
					}
				}
				try
				{
					if (mySheet.HPageBreaks.Count < 1024)
					{
						if (myPageLength == "L")
						{
							mySheet.HPageBreaks.Add("A" + Convert.ToString(iStartRow));
						}
						if (myPageLength == "S" && shortPageState == 2)
						{
							mySheet.HPageBreaks.Add("A" + Convert.ToString(iStartRow));
						}
					}
				}
				catch
				{
				}
			}
			F_ProgPos++;
			if (i % 5 == 0)
			{
				Application.DoEvents();
			}
		}
		if (F_IsLockAn)
		{
			if (!FIsShowCost && FExpType == "BUD")
			{
				mySheet.Protect(ProtectionType.Contents, "ARCH13139409", null);
			}
			else if (FExpType == "BID")
			{
				mySheet.Protect(ProtectionType.Contents, "ARCH13139409", null);
			}
		}
		return 0;
	}

