	private void FindMaxAndChangeValue(double lCost, double eCost, double mCost, double wCost, int DecDigital, double Amt, out double LValue, out double EValue, out double MValue, out double WValue)
	{
		LValue = 0.0;
		EValue = 0.0;
		MValue = 0.0;
		WValue = 0.0;
		if (lCost >= eCost && lCost >= mCost && lCost >= wCost)
		{
			lCost = Amt - PubTools.ARound(eCost, DecDigital) - PubTools.ARound(mCost, DecDigital) - PubTools.ARound(wCost, DecDigital);
			LValue = lCost;
			EValue = PubTools.ARound(eCost, DecDigital);
			MValue = PubTools.ARound(mCost, DecDigital);
			WValue = PubTools.ARound(wCost, DecDigital);
		}
		else if (eCost >= lCost && eCost >= mCost && eCost >= wCost)
		{
			eCost = Amt - PubTools.ARound(lCost, DecDigital) - PubTools.ARound(mCost, DecDigital) - PubTools.ARound(wCost, DecDigital);
			LValue = PubTools.ARound(lCost, DecDigital);
			EValue = eCost;
			MValue = PubTools.ARound(mCost, DecDigital);
			WValue = PubTools.ARound(wCost, DecDigital);
		}
		else if (mCost >= lCost && mCost >= eCost && mCost >= wCost)
		{
			mCost = Amt - PubTools.ARound(lCost, DecDigital) - PubTools.ARound(eCost, DecDigital) - PubTools.ARound(wCost, DecDigital);
			LValue = PubTools.ARound(lCost, DecDigital);
			EValue = PubTools.ARound(eCost, DecDigital);
			MValue = mCost;
			WValue = PubTools.ARound(wCost, DecDigital);
		}
		else if (wCost >= lCost && wCost >= eCost && wCost >= mCost)
		{
			wCost = Amt - PubTools.ARound(lCost, DecDigital) - PubTools.ARound(eCost, DecDigital) - PubTools.ARound(mCost, DecDigital);
			LValue = PubTools.ARound(lCost, DecDigital);
			EValue = PubTools.ARound(eCost, DecDigital);
			MValue = PubTools.ARound(mCost, DecDigital);
			WValue = wCost;
		}
	}

