				mySheet.Cells["E" + iStartRow].PutValue(PubTools.Str2Double(ClientDS1[i]["costB"].ToString()));
			}
			if (ClientDS1[i]["CostDecB"] != DBNull.Value)
			{
				if (PubTools.Str2Int(ClientDS1[i]["CostDecB"]) != decAnalCost)
				{
					if (PubTools.Str2Int(ClientDS1[i]["CostDecB"]) == 0)
					{
						myRange.Style = ((ClientDS1[i]["ItemNum"].ToString().Trim() != "1" && F_IsNoMiddle) ? myStylePri_Cost2A : myStylePri_CostA);
					}
					else if (PubTools.Str2Int(ClientDS1[i]["CostDecB"]) == 1)
					{
						myRange.Style = ((ClientDS1[i]["ItemNum"].ToString().Trim() != "1" && F_IsNoMiddle) ? myStylePri_Cost2B : myStylePri_CostB);
					}
					else if (PubTools.Str2Int(ClientDS1[i]["CostDecB"]) == 2)
					{
						myRange.Style = ((ClientDS1[i]["ItemNum"].ToString().Trim() != "1" && F_IsNoMiddle) ? myStylePri_Cost2C : myStylePri_CostC);
					}
					else if (PubTools.Str2Int(ClientDS1[i]["CostDecB"]) == 3)
					{
						myRange.Style = ((ClientDS1[i]["ItemNum"].ToString().Trim() != "1" && F_IsNoMiddle) ? myStylePri_Cost2D : myStylePri_CostD);
					}
					else if (PubTools.Str2Int(ClientDS1[i]["CostDecB"]) == 4)
					{
						myRange.Style = ((ClientDS1[i]["ItemNum"].ToString().Trim() != "1" && F_IsNoMiddle) ? myStylePri_Cost2E : myStylePri_CostE);
					}
					else
					{
						myRange.Style = ((ClientDS1[i]["ItemNum"].ToString().Trim() != "1" && F_IsNoMiddle) ? myStylePri_Cost2 : myStylePri_Cost);
					}
				}
				else
				{
					myRange.Style = ((ClientDS1[i]["ItemNum"].ToString().Trim() != "1" && F_IsNoMiddle) ? myStylePri_Cost2 : myStylePri_Cost);
				}
			}
			else
			{
				myRange.Style = ((ClientDS1[i]["ItemNum"].ToString().Trim() != "1" && F_IsNoMiddle) ? myStylePri_Cost2 : myStylePri_Cost);
			}
			if (ClientDS1[i]["memoB"].ToString().Trim().IndexOf("*") > -1 && PubTools.Str2Int(ClientDS1[i]["CostDecB"]) == decAnalCost)
			{
				myRange.Style = ((ClientDS1[i]["ItemNum"].ToString().Trim() != "1" && F_IsNoMiddle) ? myStylePri_Cost2F : myStylePri_CostF);
			}
			myRange = myCells.CreateRange("F" + Convert.ToString(iStartRow), "F" + Convert.ToString(iStartRow));
			if (!FIsShowCost && FExpType == "BUD")
			{
				mySheet.Cells["F" + Convert.ToString(iStartRow)].Formula = "=D" + iStartRow + "*E" + iStartRow;
			}
			else if (ClientDS1[i]["amountB"] == DBNull.Value || Convert.ToDouble(ClientDS1[i]["amountB"]) == 0.0 || ((ClientDS1[i]["pccesCodeB"].ToString().Length > 0) ? ClientDS1[i]["pccesCodeB"].ToString().Substring(0, 1) : "") == "#" || ClientDS1[i]["ItemNum"].ToString() != "1")
			{
				mySheet.Cells["F" + iStartRow].PutValue("");
			}
			else
			{
				mySheet.Cells["F" + iStartRow].PutValue(PubTools.Str2Double(ClientDS1[i]["amountB"].ToString()));
			}
			if (ClientDS1[i]["AmtDecB"] != DBNull.Value)
			{
				if (PubTools.Str2Int(ClientDS1[i]["AmtDecB"]) != decAnalAmt)
				{
					if (PubTools.Str2Int(ClientDS1[i]["AmtDecB"]) == 0)
					{
						myRange.Style = ((ClientDS1[i]["ItemNum"].ToString().Trim() != "1" && F_IsNoMiddle) ? myStylePri_Amt2A : myStylePri_AmtA);
					}
					else if (PubTools.Str2Int(ClientDS1[i]["AmtDecB"]) == 1)
					{
						myRange.Style = ((ClientDS1[i]["ItemNum"].ToString().Trim() != "1" && F_IsNoMiddle) ? myStylePri_Amt2B : myStylePri_AmtB);
					}
					else if (PubTools.Str2Int(ClientDS1[i]["AmtDecB"]) == 2)
					{
						myRange.Style = ((ClientDS1[i]["ItemNum"].ToString().Trim() != "1" && F_IsNoMiddle) ? myStylePri_Amt2C : myStylePri_AmtC);
					}
					else if (PubTools.Str2Int(ClientDS1[i]["AmtDecB"]) == 3)
					{
						myRange.Style = ((ClientDS1[i]["ItemNum"].ToString().Trim() != "1" && F_IsNoMiddle) ? myStylePri_Amt2D : myStylePri_AmtD);
					}
					else if (PubTools.Str2Int(ClientDS1[i]["AmtDecB"]) == 4)
					{
						myRange.Style = ((ClientDS1[i]["ItemNum"].ToString().Trim() != "1" && F_IsNoMiddle) ? myStylePri_Amt2E : myStylePri_AmtE);
					}
					else
					{
						myRange.Style = ((ClientDS1[i]["ItemNum"].ToString().Trim() != "1" && F_IsNoMiddle) ? myStylePri_Amt2 : myStylePri_Amt);
					}
				}
				else
				{
					myRange.Style = ((ClientDS1[i]["ItemNum"].ToString().Trim() != "1" && F_IsNoMiddle) ? myStylePri_Amt2 : myStylePri_Amt);
				}
			}
			else
			{
				myRange.Style = ((ClientDS1[i]["ItemNum"].ToString().Trim() != "1" && F_IsNoMiddle) ? myStylePri_Amt2 : myStylePri_Amt);
			}
			if (FExpType == "BUD" && Convert.ToString(ClientDS1[i]["cNameB"]).Trim() == "計")
			{
				mySheet.Cells["F" + iStartRow].PutValue(PubTools.ARound(PubTools.Str2Double(ClientDS1[i]["amountB"].ToString()), decItemCost));
			}
			if (Convert.ToString(ClientDS1[i]["cNameB"]).Trim() != "合計" && Convert.ToString(ClientDS1[i]["cNameB"]).Trim() != "計")
			{
				string sssTmp = mySheet.Cells["F" + iStartRow].StringValue;
				if (sssTmp != "")
				{
					dRunningSum += PubTools.Str2Double(mySheet.Cells["F" + iStartRow].DoubleValue);
				}
			}
			myRange = myCells.CreateRange("G" + Convert.ToString(iStartRow), "G" + Convert.ToString(iStartRow));
			mySheet.Cells["G" + iStartRow].PutValue(ClientDS1[i]["memoB"].ToString());
			myRange.Style = ((ClientDS1[i]["ItemNum"].ToString().Trim() != "1" && F_IsNoMiddle) ? myStylePri_Memo2 : myStylePri_Memo);
			iDoneRows++;
			iStartRow++;
			iSubItems++;
			if ((i + 1 < ClientDS1.Count && ClientDS1[i + 1]["NewPage"].ToString().Trim() == "Y") || i + 1 == ClientDS1.Count)
			{
				myAnaRows = iSubItems;
				int iBlankRows;
				if (myPageLength == "S")
				{
					shortPageState++;
					if (shortPageState > 2)
					{
						shortPageState = 1;
					}
					iBlankRows = 12 - myAnaRows;
				}
				else
				{
					iBlankRows = 28 - myAnaRows;
				}
				if (iBlankRows > 0)
				{
					myRange = myCells.CreateRange("B" + Convert.ToString(iStartRow), "G" + Convert.ToString(iStartRow + iBlankRows));
					myRange.Style = myStylePri_Empty1;
					myRange.RowHeight = 19.5;
					iStartRow += iBlankRows;
				}
				iSubItems = 0;
				bool IsLastItem = ClientDS1[i]["LastItem"].ToString().Trim() == "Y";
				double xlRate = PubTools.Str2Double(ClientDS1[i]["lRate"].ToString());
				double xmRate = PubTools.Str2Double(ClientDS1[i]["mRate"].ToString());
				double xeRate = PubTools.Str2Double(ClientDS1[i]["eRate"].ToString());
				double xwRate = PubTools.Str2Double(ClientDS1[i]["wRate"].ToString());
				bool IsAll4RateZero = ((xlRate == 0.0 && xeRate == 0.0 && xmRate == 0.0 && xwRate == 0.0) ? true : false);
				double ParentCost = PubTools.Str2Double(ClientDS1[i]["cost"].ToString());
				myRange = myCells.CreateRange("B" + Convert.ToString(iStartRow), "C" + Convert.ToString(iStartRow));
				mySheet.Cells.Merge(iStartRow - 1, 1, 1, 2);
				if (IsAll4RateZero)
				{
					mySheet.Cells["B" + iStartRow].PutValue(Convert.ToString("人工：" + (IsLastItem ? string.Format("{0:N" + decAnalAmt + "}", "") : "").PadLeft(16, ' ') + "    ") + Convert.ToString("機具：" + (IsLastItem ? string.Format("{0:N" + decAnalAmt + "}", "") : "").PadLeft(16, ' ')));
				}
				else
				{
					mySheet.Cells["B" + iStartRow].PutValue(Convert.ToString("人工：" + (IsLastItem ? string.Format("{0:N" + decAnalAmt + "}", xlRate) : "").PadLeft(16, ' ') + "    ") + Convert.ToString("機具：" + (IsLastItem ? string.Format("{0:N" + decAnalAmt + "}", xeRate) : "").PadLeft(16, ' ')));
				}
				myRange.Style = myStylePri_Btm1;
				myRange.RowHeight = 19.5;
				myRange = myCells.CreateRange("D" + Convert.ToString(iStartRow), "E" + Convert.ToString(iStartRow + 1));
				mySheet.Cells.Merge(iStartRow - 1, 3, 2, 2);
				mySheet.Cells["D" + iStartRow].PutValue("每 " + ClientDS1[i]["unitName"].ToString().Trim() + " 單價計");
				myRange.Style = myStylePri_Btm22;
				myRange = myCells.CreateRange("F" + Convert.ToString(iStartRow), "F" + Convert.ToString(iStartRow + 1));
				mySheet.Cells.Merge(iStartRow - 1, 5, 2, 1);
				mySheet.Cells["F" + iStartRow].PutValue(IsLastItem ? PubTools.Str2Decimal(ParentCost) : 0m);
				myRange.Style = myStylePri_BtmAmt;
				myRange = myCells.CreateRange("G" + Convert.ToString(iStartRow), "G" + Convert.ToString(iStartRow + 1));
				mySheet.Cells.Merge(iStartRow - 1, 6, 2, 1);
				myRange.Style = myStylePri_BtmAmt;
				iStartRow++;
				myRange = myCells.CreateRange("B" + Convert.ToString(iStartRow), "C" + Convert.ToString(iStartRow));
				mySheet.Cells.Merge(iStartRow - 1, 1, 1, 2);
				if (IsAll4RateZero)
				{
					mySheet.Cells["B" + iStartRow].PutValue(Convert.ToString("材料：" + (IsLastItem ? string.Format("{0:N" + decAnalAmt + "}", "") : "").PadLeft(16, ' ') + "    ") + Convert.ToString("雜項：" + (IsLastItem ? string.Format("{0:N" + decAnalAmt + "}", "") : "").PadLeft(16, ' ')));
				}
				else
				{
					mySheet.Cells["B" + iStartRow].PutValue(Convert.ToString("材料：" + (IsLastItem ? string.Format("{0:N" + decAnalAmt + "}", xmRate) : "").PadLeft(16, ' ') + "    ") + Convert.ToString("雜項：" + (IsLastItem ? string.Format("{0:N" + decAnalAmt + "}", xwRate) : "").PadLeft(16, ' ')));
				}
				myRange.Style = myStylePri_Btm2;
				myRange.RowHeight = 19.5;
				iStartRow++;
				if (myPageLength == "L")
				{
					mySheet.HPageBreaks.Add("A" + Convert.ToString(iStartRow));
				}
				if (myPageLength == "S" && shortPageState == 2)
				{
					mySheet.HPageBreaks.Add("A" + Convert.ToString(iStartRow));
				}
			}
			F_ProgPos++;
			if (i % 5 == 0)
			{
				Application.DoEvents();
			}
		}
		return 0;
	}

	private int IVO_SummaryIssue()
