		myStyleSum_AmountBtm.Borders[BorderType.TopBorder].LineStyle = CellBorderType.Thin;
		myStyleSum_AmountBtm.Borders[BorderType.BottomBorder].LineStyle = CellBorderType.Thin;
		myStyleSum_AmountBtm.Borders[BorderType.LeftBorder].LineStyle = CellBorderType.Thin;
		myStyleSum_AmountBtm.Borders[BorderType.RightBorder].LineStyle = CellBorderType.Thin;
		iStyleIndex = myExcel.Styles.Add();
		Style myStypeSum_Memo = myExcel.Styles[iStyleIndex];
		myStypeSum_Memo.Font.Size = 10;
		myStypeSum_Memo.Font.IsBold = false;
		myStypeSum_Memo.Font.Name = FontFace;
		myStypeSum_Memo.HorizontalAlignment = TextAlignmentType.Left;
		myStypeSum_Memo.ShrinkToFit = F_AutoShrink;
		myStypeSum_Memo.Borders[BorderType.TopBorder].LineStyle = CellBorderType.Thin;
		myStypeSum_Memo.Borders[BorderType.BottomBorder].LineStyle = CellBorderType.None;
		myStypeSum_Memo.Borders[BorderType.LeftBorder].LineStyle = CellBorderType.Thin;
		myStypeSum_Memo.Borders[BorderType.RightBorder].LineStyle = CellBorderType.Thin;
		iStyleIndex = myExcel.Styles.Add();
		Style myStypeSum_Empty1 = myExcel.Styles[iStyleIndex];
		myStypeSum_Empty1.Font.Size = 10;
		myStypeSum_Empty1.Font.IsBold = false;
		myStypeSum_Empty1.Font.Name = FontFace;
		myStypeSum_Empty1.Borders[BorderType.TopBorder].LineStyle = CellBorderType.None;
		myStypeSum_Empty1.Borders[BorderType.BottomBorder].LineStyle = CellBorderType.None;
		myStypeSum_Empty1.Borders[BorderType.LeftBorder].LineStyle = CellBorderType.Thin;
		myStypeSum_Empty1.Borders[BorderType.RightBorder].LineStyle = CellBorderType.Thin;
		return 0;
	}

	private int GetDTDetailRowIndex(ref DataTable DT_New, int iSNo)
	{
		int RetV = -1;
		for (int i = 0; i < DT_New.Rows.Count; i++)
		{
			if (PubTools.Str2Int(DT_New.Rows[i]["sNo"]) == iSNo && PubTools.Str2Int(DT_New.Rows[i]["ItemNum"]) == 1)
			{
				RetV = i;
				break;
			}
		}
		return RetV;
	}

