							{
								referenceText = "同";
							}
						}
						referenceText = "詳單價分析表";
					}
				}
				itemNo = string.Empty;
			}
			dvDetailList.Dispose();
			dvDetailList = null;
		}
		PubTools.WriteRoughlyLog(tmp_AL1);
		return myTable;
	}

	private DataTable Analysis_Rep()
	{
		ArrayList tmp_AL1 = new ArrayList();
