		{
			bool childrenOrderBySerailNumber = false;
			bool printDuplication = F_AnaRepeat == "1";
			bool orderByPccesCode = F_AnaSortOrder == "1";
			string allowSort = CommonMethods.IniReadValue(AppLocation + "OptionSet.ini", "BreakDownData", "AllowSort");
			if (allowSort.ToUpper() == "TRUE")
			{
				childrenOrderBySerailNumber = true;
			}
			if (F_IsPrice)
			{
				myTable = reportManager.GetCostBreakDownList(FProjectCode, childrenOrderBySerailNumber, orderByPccesCode, printDuplication, F_IsAnaMemo, F_IsAnaPccesCode, F_IsAnaAnaMark, F_IsAnaExtCode).Tables[0];
			}
			else
			{
				myTable = reportManager.GetRequestBidCostBreakDownList(FProjectCode, childrenOrderBySerailNumber, orderByPccesCode, printDuplication, F_isRequestBidAnalysisShowQtyL, F_isRequestBidAnalysisShowQtyE, F_isRequestBidAnalysisShowQtyM, F_isRequestBidAnalysisShowQtyW, F_IsAnaMemo, F_IsAnaPccesCode, F_IsAnaAnaMark, F_IsAnaExtCode).Tables[0];
			}
		}
		else
		{
			Repclass repcom = new Repclass(tmp_AL1);
			repcom.ps_sckind = FExpType;
			repcom.ps_analysisMark = F_AnaMark;
			memoKind = (F_IsAnaMemo ? "1" : "0");
			memoKind += (F_IsAnaPccesCode ? "1" : "0");
			memoKind += (F_IsAnaAnaMark ? "1" : "0");
			memoKind += (F_IsAnaExtCode ? "1" : "0");
			repcom.ps_memo = memoKind;
			repcom._IsOldReCal = F_IsOldReCal;
			repcom.ps_filter = F_AnaRepeat;
			if (F_AnaRepeat == "1")
			{
				repcom._Repeat = true;
			}
			repcom.ps_showcost = (F_IsPrice ? "1" : "0");
			repcom.ps_PrintByPccesCode = ((F_AnaSortOrder == "1") ? "Y" : "N");
			repcom.ps_ExecutePath = CommonMethods.ExtractFilePath(Application.ExecutablePath);
			repcom._Mode = F_AnaSortOrderDet;
			repcom.ps_Issue = F_chgCount;
			repcom._isRequestBidAnalysisShowQtyL = F_isRequestBidAnalysisShowQtyL;
			repcom._isRequestBidAnalysisShowQtyE = F_isRequestBidAnalysisShowQtyE;
			repcom._isRequestBidAnalysisShowQtyM = F_isRequestBidAnalysisShowQtyM;
			repcom._isRequestBidAnalysisShowQtyW = F_isRequestBidAnalysisShowQtyW;
			myTable = repcom.AnalysisRpt(FProjectCode);
			repcom = null;
		}
		printNoAndItemNoPair = new Dictionary<string, string>();
		string printNo = string.Empty;
		foreach (DataRow row in myTable.Rows)
		{
			if (printNo != row["printNo"].ToString())
			{
				printNoAndItemNoPair.Add(row["printNo"].ToString(), row["itemNo"].ToString());
				printNo = row["printNo"].ToString();
			}
		}
		myTable.Columns.Add("LastItem", Type.GetType("System.String"));
		string ls_code = "";
		if (F_AnaSortOrder == "1")
		{
			DataTable tmpdt = myTable.Copy();
			DataView tmpdv = tmpdt.DefaultView;
			tmpdv.Sort = "PccesCode,seq";
			myTable.Clear();
			int RecNo = 0;
			string tmpItemNo = "";
			for (int i = 0; i < tmpdv.Count; i++)
			{
				if (ls_code != tmpdv[i]["PccesCode"].ToString())
				{
					ls_code = tmpdv[i]["PccesCode"].ToString();
					tmpItemNo = tmpdv[i]["ItemNo"].ToString();
					RecNo++;
				}
				if (!(tmpItemNo == tmpdv[i]["ItemNo"].ToString()))
				{
					continue;
				}
				DataRow dr = myTable.NewRow();
				for (int j = 0; j < myTable.Columns.Count; j++)
				{
					if (myTable.Columns[j].ColumnName.ToUpper() == "ITEMNO")
					{
						dr[j] = RecNo.ToString().PadLeft(5, ' ');
					}
					else if (myTable.Columns[j].ColumnName.ToUpper() == "PRINTNO")
					{
						dr[j] = RecNo.ToString().PadLeft(20, '0');
					}
					else
					{
						dr[j] = tmpdv[i][j];
					}
				}
				myTable.Rows.Add(dr);
			}
		}
		else if (F_AnaRepeat == "0")
		{
			DataTable tmpdt = myTable.Copy();
			DataView tmpdv = tmpdt.DefaultView;
			tmpdv.Sort = "PccesCode,seq";
			DataTable DT = myTable.Copy();
			DataTable DTTemp = CheckSortDetail(DT);
			DTTemp.CaseSensitive = true;
			DataView DVTemp = new DataView(DTTemp);
			myTable.Clear();
			string tmpItemNo = "";
			if (F_DetailMaster)
			{
				for (int i = 0; i < tmpdv.Count; i++)
				{
					if (ls_code != tmpdv[i]["PccesCode"].ToString() || (F_IsRepeatDetailAnalysis && tmpItemNo != tmpdv[i]["ItemNo"].ToString() && tmpdv[i]["IsDetail"].ToString().Trim() == "ISDETAIL"))
					{
						ls_code = tmpdv[i]["PccesCode"].ToString().Trim();
						tmpItemNo = tmpdv[i]["ItemNo"].ToString();
					}
					DVTemp.RowFilter = "PccesCode ='" + ls_code + "'";
					if (!F_IsRepeatDetailAnalysis)
					{
						if (DVTemp.Count > 0)
						{
							if (DVTemp[0]["IsDetail"].ToString().Trim() == "ISDETAIL")
							{
								tmpItemNo = DVTemp[0]["ItemNo"].ToString();
							}
							if (tmpdv[i]["IsDetail"].ToString().Trim() == "ISDETAIL" && tmpItemNo == tmpdv[i]["ItemNo"].ToString())
							{
								DataRow dr = myTable.NewRow();
								for (int j = 0; j < myTable.Columns.Count; j++)
								{
									dr[j] = tmpdv[i][j];
								}
								myTable.Rows.Add(dr);
							}
						}
						else if (tmpItemNo == tmpdv[i]["ItemNo"].ToString())
						{
							DataRow dr = myTable.NewRow();
							for (int j = 0; j < myTable.Columns.Count; j++)
							{
								dr[j] = tmpdv[i][j];
							}
							myTable.Rows.Add(dr);
						}
					}
					else if (tmpItemNo == tmpdv[i]["ItemNo"].ToString())
					{
						DataRow dr = myTable.NewRow();
						for (int j = 0; j < myTable.Columns.Count; j++)
						{
							dr[j] = tmpdv[i][j];
						}
						myTable.Rows.Add(dr);
					}
				}
			}
			else
			{
				for (int i = 0; i < tmpdv.Count; i++)
				{
					if (ls_code != tmpdv[i]["PccesCode"].ToString() || (F_IsRepeatDetailAnalysis && tmpItemNo != tmpdv[i]["ItemNo"].ToString() && tmpdv[i]["IsDetail"].ToString().Trim() == "ISDETAIL"))
					{
						ls_code = tmpdv[i]["PccesCode"].ToString();
						tmpItemNo = tmpdv[i]["ItemNo"].ToString();
					}
					if (tmpItemNo == tmpdv[i]["ItemNo"].ToString())
					{
						DataRow dr = myTable.NewRow();
						for (int j = 0; j < myTable.Columns.Count; j++)
						{
							dr[j] = tmpdv[i][j];
						}
						myTable.Rows.Add(dr);
					}
				}
			}
			if (chkCnE)
			{
				DataTable tmpdt2 = myTable.Copy();
				DataView tmpdv2 = tmpdt2.DefaultView;
				tmpdv2.Sort = "seq";
				myTable.Clear();
				for (int i = 0; i < tmpdv2.Count; i++)
				{
					DataRow dr = myTable.NewRow();
					for (int j = 0; j < myTable.Columns.Count; j++)
					{
						dr[j] = tmpdv2[i][j];
					}
					myTable.Rows.Add(dr);
				}
			}
		}
		for (int i = myTable.Rows.Count; i > 0; i--)
		{
			if (ls_code != myTable.Rows[i - 1]["pccesCode"].ToString().Trim())
			{
				myTable.Rows[i - 1]["LastItem"] = "Y";
			}
			else
			{
				myTable.Rows[i - 1]["LastItem"] = "N";
			}
			ls_code = myTable.Rows[i - 1]["pccesCode"].ToString().Trim();
		}
		if (!chkCnE)
		{
			DataView dv1 = myTable.DefaultView;
			myTable.CaseSensitive = true;
			dv1.Sort = "PccesCode";
			foreach (DataRow dr in myTable.Rows)
			{
				string ls_BPccesCode = dr["pccescodeB"].ToString().Trim();
				if (!(dr["analysisb"].ToString().Trim() == "1"))
				{
					continue;
				}
				DataRow dataRow;
				if (F_AnaRepeat == "0")
				{
					dv1.RowFilter = "PccesCode = '" + ls_BPccesCode + "' ";
					if (dv1.Count > 0)
					{
						(dataRow = dr)["memob"] = string.Concat(dataRow["memob"], "同", dv1[0]["ItemNo"].ToString().Trim());
					}
					continue;
				}
				string l_str = "";
				dv1.RowFilter = "PccesCode = '" + ls_BPccesCode + "' ";
				if (dv1.Count <= 0)
				{
					continue;
				}
				l_str = "同" + dv1[0]["ItemNo"].ToString().Trim();
				for (int i = 0; i < dv1.Count; i++)
				{
					if (dv1[i]["IsDetail"].ToString().Trim() == "ISDETAIL")
					{
						l_str = "同" + dv1[i]["ItemNo"].ToString().Trim();
						break;
					}
				}
				(dataRow = dr)["memob"] = string.Concat(dataRow["memob"], l_str);
			}
		}
		return myTable;
	}

	private DataTable CheckSortDetail(DataTable DT)
	{
		DataView DV = new DataView(DT);
		DV.Sort = "PccesCode,seq";
		DV.RowFilter = "IsDetail = 'IsDetail' ";
		DataTable DTTemp = new DataTable();
		DTTemp.Columns.Add("PccesCode", Type.GetType("System.String"));
		DTTemp.Columns.Add("ItemNo", Type.GetType("System.String"));
		DTTemp.Columns.Add("pubCode", Type.GetType("System.String"));
		DTTemp.Columns.Add("IsDetail", Type.GetType("System.String"));
		string ls_code = "";
		string tmpItemNo = "";
		int iCount = 0;
		for (int i = 0; i < DV.Count; i++)
		{
			if (ls_code != DV[i]["PccesCode"].ToString() || (F_IsRepeatDetailAnalysis && tmpItemNo != DV[i]["ItemNo"].ToString() && DV[i]["IsDetail"].ToString().Trim() == "ISDETAIL"))
			{
				ls_code = DV[i]["PccesCode"].ToString();
				tmpItemNo = DV[i]["ItemNo"].ToString();
				iCount = 0;
			}
			if (tmpItemNo == DV[i]["ItemNo"].ToString() && iCount == 0)
			{
				iCount++;
				DataRow dr = DTTemp.NewRow();
				dr["PccesCode"] = DV[i]["PccesCode"].ToString();
				dr["ItemNo"] = DV[i]["ItemNo"].ToString();
				dr["IsDetail"] = DV[i]["IsDetail"].ToString();
				DTTemp.Rows.Add(dr);
			}
		}
		return DTTemp;
	}

