	private void ExtraWork(int opTypeIndex)
	{
		myTable.Columns.Add("cname_line", Type.GetType("System.Int16"));
		myTable.Columns.Add("ename_line", Type.GetType("System.Int16"));
		myTable.Columns.Add("line_len", Type.GetType("System.Int16"));
		string gTableName = Guid.NewGuid().ToString();
		Class1 cl1 = new Class1(UserID);
		NewDT = myTable.Copy();
		NewDT.Clear();
		NewDT.Columns.Add("NewPage", Type.GetType("System.String"));
		NewDT.Columns.Add("ItemNum", Type.GetType("System.Int16"));
		NewDT.Columns.Add("ColNo", Type.GetType("System.Int16"));
		int RowNo = 0;
		foreach (DataRow dr in myTable.Rows)
		{
			int x = 1;
			string ColName = "";
			ColName = ((opTypeIndex != 3) ? "cname" : "cNameB");
			int Memo_len = 0;
			switch (opTypeIndex)
			{
			case 1:
				Memo_len = 14;
				break;
			case 2:
				Memo_len = 14;
				break;
			case 3:
				Memo_len = 14;
				break;
			case 4:
				Memo_len = 20;
				break;
			}
			string[] tmpm = new string[0];
			switch (opTypeIndex)
			{
			case 3:
				try
				{
					tmpm = cl1.GetCstring(dr["memoB"].ToString().Replace(" ", ""), Memo_len);
				}
				catch (Exception ex)
				{
					CommonMethods.LogFile("Pcces46", "M", "Conversion.cs" + ex.Message);
				}
				break;
			default:
				try
				{
					tmpm = cl1.GetCstring(dr["memo"].ToString(), Memo_len);
				}
				catch (Exception ex)
				{
					CommonMethods.LogFile("Pcces46", "M", "Conversion.cs" + ex.Message);
				}
				break;
			case 4:
				break;
			}
			string[] tmpc = cl1.GetCstring(dr[ColName].ToString(), li_len);
			string[] tmpe = new string[0];
			if (dr["PccesCode"].ToString().Trim() == "V0000000000")
			{
				tmpe = new string[0];
			}
			Application.DoEvents();
			if (chkCnE)
			{
				tmpe = ((opTypeIndex != 3) ? cl1.GetEstring(dr["ename"].ToString(), li_len) : cl1.GetEstring(dr["eNameB"].ToString(), li_len));
			}
			int RowCount = 0;
			RowCount = ((tmpe.Length + tmpc.Length <= tmpm.Length) ? tmpm.Length : (tmpe.Length + tmpc.Length));
			for (int i = 0; i < tmpc.Length; i++)
			{
				DataRow ndr = NewDT.NewRow();
				for (int j = 0; j < myTable.Columns.Count; j++)
				{
					ndr[j] = dr[j];
				}
				try
				{
					switch (opTypeIndex)
					{
					case 3:
						ndr["memoB"] = tmpm[x - 1];
						break;
					default:
						ndr["memo"] = tmpm[x - 1];
						break;
					case 4:
						break;
					}
				}
				catch
				{
					try
					{
						switch (opTypeIndex)
						{
						case 3:
							ndr["memoB"] = "";
							break;
						default:
							ndr["memo"] = "";
							break;
						case 4:
							break;
						}
					}
					catch (Exception ex)
					{
						CommonMethods.LogFile("Pcces46", "M", "Conversion.cs" + ex.Message);
					}
				}
				if (chkCnE)
				{
					switch (x)
					{
					default:
						if (opTypeIndex != 4)
						{
							ndr["ItemNo"] = "";
						}
						break;
					case 2:
						if (opTypeIndex != 4)
						{
							ndr["ItemNo"] = "";
						}
						if (opTypeIndex == 3)
						{
							ndr["UnitNameB"] = ndr["eUnitB"];
						}
						else
						{
							ndr["UnitName"] = ndr["eUnit"];
						}
						break;
					case 1:
						break;
					}
				}
				ndr[ColName] = tmpc[i];
				bool lb_NewPage = false;
				if (opTypeIndex == 2 && x == 1 && dr["PrintNo"].ToString().Trim().Length == 4)
				{
					lb_NewPage = true;
				}
				if (lb_NewPage)
				{
					ndr["NewPage"] = "Y";
					RowNo = 0;
				}
				else if (i == 0 && RowCount + RowNo > 40)
				{
					ndr["NewPage"] = "Y";
					RowNo = 0;
				}
				else
				{
					ndr["NewPage"] = "N";
				}
				ndr["ItemNum"] = x;
				ndr["ColNo"] = RowNo;
				RowNo++;
				NewDT.Rows.Add(ndr);
				x++;
			}
			if (chkCnE)
			{
				for (int i = 0; i < tmpe.Length; i++)
				{
					DataRow ndr = NewDT.NewRow();
					for (int j = 0; j < myTable.Columns.Count; j++)
					{
						ndr[j] = dr[j];
					}
					try
					{
						if (opTypeIndex == 3)
						{
							ndr["memoB"] = tmpm[x - 1];
						}
						else
						{
							ndr["memo"] = tmpm[x - 1];
						}
					}
					catch
					{
						try
						{
							if (opTypeIndex == 3)
							{
								ndr["memoB"] = "";
							}
							else
							{
								ndr["memo"] = "";
							}
						}
						catch (Exception ex)
						{
							CommonMethods.LogFile("Pcces46", "M", "Conversion.cs" + ex.Message);
						}
					}
					if (x != 2)
					{
						ndr["UnitName"] = "";
					}
					else if (opTypeIndex == 3)
					{
						ndr["UnitNameB"] = ndr["eUnitB"];
					}
					else
					{
						ndr["UnitName"] = ndr["eUnit"];
					}
					if (opTypeIndex != 4)
					{
						ndr["ItemNo"] = "";
					}
					ndr[ColName] = tmpe[i];
					ndr["NewPage"] = "N";
					ndr["ColNo"] = RowNo;
					ndr["ItemNum"] = x;
					RowNo++;
					NewDT.Rows.Add(ndr);
					x++;
				}
			}
			for (; x - 1 < tmpm.Length; x++)
			{
				DataRow ndr = NewDT.NewRow();
				ndr["PccesCode"] = dr["PccesCode"];
				if (opTypeIndex == 3)
				{
					ndr["PrintNo"] = dr["PrintNo"];
					ndr["ReportPrintNo"] = dr["ReportPrintNo"].ToString().Trim();
					ndr["ItemNo"] = dr["ItemNo"];
				}
				ndr["ItemNum"] = x;
				ndr["NewPage"] = "N";
				ndr["ColNo"] = RowNo;
				if (opTypeIndex == 3)
				{
					ndr["memoB"] = tmpm[x - 1].Replace(" ", "");
				}
				else
				{
					ndr["memo"] = tmpm[x - 1];
				}
				RowNo++;
				NewDT.Rows.Add(ndr);
			}
			if (chkCnE && x % 2 == 0)
			{
				DataRow ndr = NewDT.NewRow();
				ndr["PccesCode"] = dr["PccesCode"];
				if (opTypeIndex == 3)
				{
					ndr["PrintNo"] = dr["PrintNo"];
					ndr["ReportPrintNo"] = dr["ReportPrintNo"].ToString().Trim();
					ndr["ItemNo"] = dr["ItemNo"];
				}
				if (opTypeIndex == 1)
				{
					ndr["IsBid"] = "Y";
				}
				ndr["ItemNum"] = x;
				ndr["NewPage"] = "N";
				ndr["ColNo"] = RowNo;
				RowNo++;
				NewDT.Rows.Add(ndr);
			}
		}
		if (opTypeIndex == 3)
		{
			string ls_PrintNo = "";
			string ls_ItemNo = "";
			if (chkCnE)
			{
				foreach (DataRow dr in NewDT.Rows)
				{
					if (ls_PrintNo != dr["PrintNo"].ToString().Trim() + dr["PccesCode"].ToString())
					{
						dr["NewPage"] = "Y";
					}
					else
					{
						dr["NewPage"] = "N";
					}
					ls_PrintNo = dr["PrintNo"].ToString().Trim() + dr["PccesCode"].ToString();
					ls_ItemNo = dr["ItemNo"].ToString().Trim();
				}
			}
			else
			{
				foreach (DataRow dr in NewDT.Rows)
				{
					if (ls_PrintNo != dr["PrintNo"].ToString().Trim() + dr["PccesCode"].ToString() || ls_ItemNo != dr["ItemNo"].ToString().Trim())
					{
						dr["NewPage"] = "Y";
					}
					else
					{
						dr["NewPage"] = "N";
					}
					ls_PrintNo = dr["PrintNo"].ToString().Trim() + dr["PccesCode"].ToString();
					ls_ItemNo = dr["ItemNo"].ToString().Trim();
				}
			}
			string ls_LastItem = "Y";
			for (int i = NewDT.Rows.Count - 1; i > -1; i--)
			{
				NewDT.Rows[i]["LastItem"] = ls_LastItem;
				ls_LastItem = NewDT.Rows[i]["NewPage"].ToString();
			}
			int PageLine = 28;
			int LineNo = 1;
			for (int k = 0; k < NewDT.Rows.Count; k++)
			{
				if (LineNo > PageLine)
				{
					LineNo = 1;
					int tmp = PubTools.Str2Int(NewDT.Rows[k]["ItemNum"].ToString());
					k = k - tmp + 1;
					NewDT.Rows[k]["NewPage"] = "Y";
				}
				NewDT.Rows[k]["ColNo"] = LineNo;
				LineNo++;
				if (k < NewDT.Rows.Count && NewDT.Rows[k]["LastItem"].ToString() == "Y")
				{
					LineNo = 1;
				}
			}
		}
		if (NewDT.Columns.IndexOf("projectCode") > -1)
		{
			for (int i = 0; i < NewDT.Rows.Count; i++)
			{
				if (opTypeIndex == 1 && (NewDT.Rows[i]["projectCode"] == DBNull.Value || NewDT.Rows[i]["projectCode"].ToString() == "") && NewDT.Rows[i]["memo"].ToString() != "")
				{
					NewDT.Rows[i]["IsBid"] = "Y";
				}
			}
		}
		Thread.Sleep(0);
	}

	private int CalRowCount_BDGTSh1(object sData)
	{
		double Temp = Convert.ToDouble(sData);
		if (Temp > 39.0 && Temp <= 58.5)
		{
			return 3;
		}
		if (Temp > 19.5 && Temp <= 39.0)
		{
			return 2;
		}
		if (Temp <= 19.5)
		{
			return 1;
		}
		return -1;
	}

	private string Replicate(string VSTR1, int VLEN)
	{
		string VSTR2 = null;
		for (int j = 0; j < VLEN; j++)
		{
			VSTR2 += VSTR1;
		}
		return VSTR2;
	}
